package org.pms.silverocean.database.pms.entities;import jakarta.persistence.*;import lombok.Getter;import lombok.NoArgsConstructor;import org.pms.silverocean.database.pms.entities.base.BaseIDEntity;import java.math.BigDecimal;import java.time.ZonedDateTime;@Entity @Table(name="pms_sale_milestone",indexes=@Index(name="idx_sale_milestone_sale",columnList="saleId,milestoneType,status")) @Getter @NoArgsConstructor public class SaleMilestone extends BaseIDEntity{private long saleId;private String milestoneType;private String status;private BigDecimal amount;private String currency;private String externalReference;private Long evidenceDocumentId;private String notes;private ZonedDateTime occurredAt;private long recordedBy;public SaleMilestone(long saleId,String type,String status,BigDecimal amount,String currency,String ref,Long document,String notes,ZonedDateTime at,long by){this.saleId=saleId;this.milestoneType=type;this.status=status;this.amount=amount;this.currency=currency;this.externalReference=ref;this.evidenceDocumentId=document;this.notes=notes;this.occurredAt=at;this.recordedBy=by;}}
